/// <summary>
/// main method.
/// </summary>
/// <param name = "_args">The arguments.</param>
public static void main(Args _args)
{
    if (!_args
        && !_args.record()
        && !_args.dataset())
    {
        throw error("@SYS25407");
    }

    if (AVADAIArchiveFormConfig::existForm(_args.callerName()))
    {
        Common		common = _args.record();
        str         url;

        if (common != null)
        {
            AVADAIArchiveFormConfig archiveFormConfig = AVADAIArchiveFormConfig::findForm(_args.callerName());
            if (archiveFormConfig.Field != '')
            {
                str dmsId = common.getFieldValue(archiveFormConfig.Field);

                if (archiveFormConfig.EscapeStr != '')
                {
                    url = strReplace(archiveFormConfig.URL, archiveFormConfig.EscapeStr, dmsId);
                }
                else
                {
                    //%1 will be replaced if no escapeStr is defined.
                    url = strfmt(archiveFormConfig.URL, dmsId); 
                }
                if (archiveFormConfig.InsertCompany == NoYes::Yes && archiveFormConfig.EscapeStrCompany)
                {
                    url = strReplace(url, archiveFormConfig.EscapeStrCompany, common.DataAreaId);
                }
                if (archiveFormConfig.Field2 && archiveFormConfig.EscapeStr2)
                {
                    str dmsId2  = common.getFieldValue(archiveFormConfig.Field2);
                    url         = strReplace(url, archiveFormConfig.EscapeStr2, dmsId2);
                }

                Browser browser = new Browser();
                browser.navigate(url);
            }
        }
    }
    else
    {
        throw error("@AVADAI:SetupMissing");
    }
}
